mapper.update:
UPDATE cynexus_appl_ai.ai_agent_task
SET status = 'PAUSED', paused_at = now(), updated_at = now()
WHERE owner_key = #{ownerKey}
  AND task_no = #{taskNo}
  AND status = 'QUEUED'
  AND deleted_at IS NULL

UPDATE cynexus_appl_ai.ai_agent_task
SET status = 'QUEUED', paused_at = NULL, next_attempt_at = now(), updated_at = now()
WHERE owner_key = #{ownerKey}
  AND task_no = #{taskNo}
  AND status = 'PAUSED'
  AND deleted_at IS NULL

UPDATE cynexus_appl_ai.ai_agent_task
SET status = 'CANCELLED', completed_at = now(), lease_owner = NULL, lease_until = NULL, updated_at = now()
WHERE owner_key = #{ownerKey}
  AND task_no = #{taskNo}
  AND status IN ('QUEUED', 'PAUSED', 'RUNNING')
  AND deleted_at IS NULL

UPDATE cynexus_appl_ai.ai_agent_task
SET run_no = #{runNo}, updated_at = now()
WHERE task_no = #{taskNo}
  AND lease_owner = #{leaseOwner}
  AND status = 'RUNNING'
  AND deleted_at IS NULL
